CREATE TABLE Users (Username TEXT NOT NULL PRIMARY KEY, Password TEXT NOT NULL, FirstName TEXT NOT NULL, LastName TEXT NOT NULL, Email TEXT);
INSERT INTO Users (Username, Password, FirstName, LastName, Email) VALUES ('ZeroUser', 'Temp123', 'ZeroUser', 'ZeroUser', 'ZeroUser');
CREATE TABLE Projects (PName VARCHAR NOT NULL, PDescription VARCHAR NOT NULL, AutoSave INTEGER NOT NULL DEFAULT 0, Admin TEXT NOT NULL DEFAULT 'ZeroUser', Validate VARCHAR NOT NULL DEFAULT 0, FOREIGN KEY(Admin) REFERENCES Users(Username), PRIMARY KEY(PName, Admin));
CREATE TABLE Access (Username TEXT NOT NULL, PName VARCHAR NOT NULL,  Admin TEXT NOT NULL, FOREIGN KEY(Username) REFERENCES Users(Username), FOREIGN KEY(PName) REFERENCES Projects(PName), FOREIGN KEY(Admin) REFERENCES Projects(Admin));
CREATE TABLE S3Buckets (PName VARCHAR NOT NULL, Admin TEXT NOT NULL, BucketName VARCHAR NOT NULL, Region VARCHAR NOT NULL, Prefix VARCHAR NOT NULL DEFAULT '', AccessKeyId VARCHAR, SecretAccessKey VARCHAR, LastSyncedAt TEXT, Endpoint TEXT, PRIMARY KEY(PName, Admin), FOREIGN KEY(PName) REFERENCES Projects(PName), FOREIGN KEY(Admin) REFERENCES Projects(Admin));
ALTER TABLE S3Buckets ADD COLUMN SyncMode VARCHAR NOT NULL DEFAULT 'download';
CREATE TABLE PreprocessingScripts (Id INTEGER PRIMARY KEY AUTOINCREMENT, PName VARCHAR NOT NULL, Admin TEXT NOT NULL, Name VARCHAR NOT NULL, Filename VARCHAR NOT NULL, UploadedAt TEXT NOT NULL, FOREIGN KEY(PName) REFERENCES Projects(PName), FOREIGN KEY(Admin) REFERENCES Projects(Admin));
CREATE TABLE PreprocessingSteps (Id INTEGER PRIMARY KEY AUTOINCREMENT, PName VARCHAR NOT NULL, Admin TEXT NOT NULL, Type VARCHAR NOT NULL, ScriptId INTEGER, Enabled INTEGER NOT NULL DEFAULT 1, StepOrder INTEGER NOT NULL DEFAULT 0, Params TEXT NOT NULL DEFAULT '{}', FOREIGN KEY(PName) REFERENCES Projects(PName), FOREIGN KEY(Admin) REFERENCES Projects(Admin), FOREIGN KEY(ScriptId) REFERENCES PreprocessingScripts(Id));
